-- Step AV-1: the four combination flush casement drawing templates.
-- Run by Nathan in the Supabase SQL editor. Safe to re-run.
--
-- Nathan (13 Oct 2026): all three of these layouts are sold, and more often
-- than French casements. They are Integrate's own templates from DrawingBoard
-- Config, CW family, group "3. Combination Flush Casements"
-- (docs/integrate-L31115-two-column-fanlights.txt):
--
--     7  Double Casement With Fanlight
--        ONE wide fanlight over two casements, LH + RH
--    12  Fanlight Over Each Casement (Configuration 1)
--        a fanlight over EACH of two casements
--    13  Full-Height Opener With Fanlight Over Fixed (Configuration 2)
--        a full-height opener beside a fanlight over a fixed sash
--    14  Fanlight Over Fixed With Full-Height Opener (Configuration 3)
--        the mirror of Configuration 2 — the fanlight column on the LEFT
--
-- Integrate's names for 12, 13 and 14 are "Configuration 1 / 2 / 3", which
-- say nothing about the layout in a template list, so each name here
-- describes the window and keeps Integrate's name in brackets. Template 7
-- keeps Integrate's own name, which already describes it. The group name is
-- Integrate's own without its leading number.
--
-- Every tree below was GENERATED by the board's own code, so each template is
-- exactly what the board would build: buildCasementFrame at Integrate's size,
-- then the transom/mullion picker, then — for 7, 13 and 14 — the picker's
-- second mode (a divider in one column or one row, which stores startDivider
-- / endDivider as Integrate does), then the operation buttons. The geometry
-- that comes out is Integrate's, cell for cell:
--
--    7   1105 x 1405  interior 1031 x 1311  A1 1031 x 301 (spans both columns), A2 493 x 983, B2 511 x 983
--    12  1299 x 1499  interior 1225 x 1405  A1 590 x 356, B1 608 x 356, A2 590 x 1022, B2 608 x 1022
--    13  1205 x 1295  interior 1131 x 1201  A1 543 x 1201 (spans both rows), B1 561 x 354, B2 561 x 820
--    14  1205 x 1295  interior 1131 x 1201  A1 561 x 354, B1 543 x 1201 (spans both rows), A2 561 x 820
--
-- The surround list is the template's own, as Integrate stores it: the Nosing
-- in Solid Redwood (frame width + 150, to the next 10 mm) and the Ogee
-- Architrave in MDF (frame size + 100, to the next 10 mm) — 7 is 1260 /
-- 2 x 1510 / 1210, 12 is 1450 / 2 x 1600 / 1400, 13 and 14 are 1360 /
-- 2 x 1400 / 1310. The nosing is what makes has_deep_window_board true, and
-- so what fires rule 251 "Windowboard" for 30 minutes of install labour.
--
-- REVIEWER EDIT (13 Oct): bottom rails are 83 on the casements and 62 on every
-- FANLIGHT (top-row sash that does not run full height) — Nathan's decision of
-- 12 Oct that new fanlights default to 62 (sql/step-as0, run: the live casement
-- profile holds casementSashPart.bottomHeight 83 and defaultFanlightBottomHeight
-- 62, and "Single Flush Casement with Fanlight" already uses 62). Integrate's
-- templates hold 83; the fixtures keep Integrate's 83 as recorded. Sort order of
-- the first template moved 40 -> 45 (40 is the stormproof template).
--
-- No stored ironmongery list: the default rules price it and follow the
-- openings (difference 4 in docs/integrate-differences.md).
--
-- Product and Quantity are both is_required (Step AQ), so the product code is
-- looked up BY LABEL — the product reference list came from Integrate and its
-- codes are not in the repository — and the script fails loudly rather than
-- writing a code that would look set and still fail the check.

BEGIN;

DO $$
DECLARE
  _profile_id    bigint;
  _casement_code text;
  _templates     jsonb := '[{"name":"Double Casement With Fanlight","sort_order":45,"tree":{"key":"item_n7t6t41","part_type":"drawingItemPart","values":{"typeOfWork":"complete_new","frameMaterialId":"softwood","sashMaterialId":"softwood","cillMaterialId":"utile","quantity":1,"surroundLines":[{"part_code":"TP61","qty":1,"length_mm":1260,"label":"Nosing in Solid Redwood"},{"part_code":"TP68","qty":2,"length_mm":1510,"label":"Ogee Architrave – height"},{"part_code":"TP68","qty":1,"length_mm":1210,"label":"Ogee Architrave – width"}]},"children":[{"key":"paint_zb43pgt","part_type":"paintAndIronmongeryPart","values":{"internalFinish":"clean_white","externalFinish":"clean_white","cillFinish":"clean_white","cutOutBrickReveal":false,"ironmongeryFinish":"PB","isCasementMpls":true},"children":[]},{"key":"notes_3tbtzoq","part_type":"notesPart","values":{},"children":[]},{"key":"price_zcu7yt7","part_type":"pricePart","values":{},"children":[]},{"key":"frame_yc7w16b","part_type":"assemblyFramePart","values":{"width":1105,"height":1405,"leftWidth":37,"rightWidth":37,"topHeight":47,"bottomHeight":47,"frameDepth":96,"jambType":"solid_profiled","frameHeadStopSize":20,"frameStileStopSize":20,"cillStopSize":20,"cillAngle":6,"rakeFrame":false,"archHead":false},"children":[{"key":"trans_ktfr1jv","part_type":"transomPart","values":{"offset":301,"thicknessInFrame":27,"transomStopSize":20,"startDivider":"0","endDivider":"0"},"children":[]},{"key":"mull_6lmou1p","part_type":"mullionPart","values":{"offset":493,"thicknessInFrame":27,"mullionStopSize":20,"startDivider":"trans_ktfr1jv","endDivider":"0"},"children":[]},{"key":"cas_4zkdieh","part_type":"casementSashPart","values":{"operation":"top_hung","casementTypeId":"open_out","thickness":54,"topHeight":62,"leftWidth":62,"rightWidth":62,"bottomHeight":62,"mechanicalClearanceLeft":4,"mechanicalClearanceRight":4,"mechanicalClearanceTop":4,"mechanicalClearanceBottom":4,"btmRailShapeId":"square","toBeReplaced":true},"children":[{"key":"cas_4zkdie