 – height"},{"part_code":"TP68","qty":1,"length_mm":1400,"label":"Ogee Architrave – width"}]},"children":[{"key":"paint_dh10cbm","part_type":"paintAndIronmongeryPart","values":{"internalFinish":"clean_white","externalFinish":"clean_white","cillFinish":"clean_white","cutOutBrickReveal":false,"ironmongeryFinish":"PB","isCasementMpls":true},"children":[]},{"key":"notes_e2bxhlv","part_type":"notesPart","values":{},"children":[]},{"key":"price_ndz7v79","part_type":"pricePart","values":{},"children":[]},{"key":"frame_kr4zksg","part_type":"assemblyFramePart","values":{"width":1299,"height":1499,"leftWidth":37,"rightWidth":37,"topHeight":47,"bottomHeight":47,"frameDepth":96,"jambType":"solid_profiled","frameHeadStopSize":20,"frameStileStopSize":20,"cillStopSize":20,"cillAngle":6,"rakeFrame":false,"archHead":false},"children":[{"key":"mull_l49yem3","part_type":"mullionPart","values":{"offset":590,"thicknessInFrame":27,"mullionStopSize":20,"startDivider":"0","endDivider":"0"},"children":[]},{"key":"trans_d3s31pr","part_type":"transomPart","values":{"offset":356,"thicknessInFrame":27,"transomStopSize":20,"startDivider":"0","endDivider":"0"},"children":[]},{"key":"cas_11r4fal","part_type":"casementSashPart","values":{"operation":"top_hung","casementTypeId":"open_out","thickness":54,"topHeight":62,"leftWidth":62,"rightWidth":62,"bottomHeight":62,"mechanicalClearanceLeft":4,"mechanicalClearanceRight":4,"mechanicalClearanceTop":4,"mechanicalClearanceBottom":4,"btmRailShapeId":"square","toBeReplaced":true},"children":[{"key":"cas_11r4fal_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":16,"glazingTolerance":2},"children":[]}]},{"key":"casementSash_bev1hme","part_type":"casementSashPart","values":{"operation":"fix","casementTypeId":"open_out","thickness":54,"topHeight":62,"leftWidth":62,"rightWidth":62,"bottomHeight":62,"mechanicalClearanceLeft":4,"mechanicalClearanceRight":4,"mechanicalClearanceTop":4,"mechanicalClearanceBottom":4,"btmRailShapeId":"square","toBeReplaced":true},"children":[{"key":"glass_bp53gvq","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":16,"glazingTolerance":2},"children":[]}]},{"key":"casementSash_313qhy2","part_type":"casementSashPart","values":{"operation":"fix","casementTypeId":"open_out","thickness":54,"topHeight":62,"leftWidth":62,"rightWidth":62,"bottomHeight":83,"mechanicalClearanceLeft":4,"mechanicalClearanceRight":4,"mechanicalClearanceTop":4,"mechanicalClearanceBottom":4,"btmRailShapeId":"square","toBeReplaced":true},"children":[{"key":"glass_6anvlpw","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":16,"glazingTolerance":2},"children":[]}]},{"key":"casementSash_hwb89hu","part_type":"casementSashPart","values":{"operation":"right_hand_hung","casementTypeId":"open_out","thickness":54,"topHeight":62,"leftWidth":62,"rightWidth":62,"bottomHeight":83,"mechanicalClearanceLeft":4,"mechanicalClearanceRight":4,"mechanicalClearanceTop":4,"mechanicalClearanceBottom":4,"btmRailShapeId":"square","toBeReplaced":true},"children":[{"key":"glass_lf1ltev","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":16,"glazingTolerance":2},"children":[]}]},{"key":"cill_vpx0gpp","part_type":"cillPart","values":{"height":47,"depth":128},"children":[]}]}]}},{"name":"Full-Height Opener With Fanlight Over Fixed (Configuration 2)","sort_order":60,"tree":{"key":"item_eyxao7e","part_type":"drawingItemPart","values":{"typeOfWork":"complete_new","frameMaterialId":"softwood","sashMaterialId":"softwood","cillMaterialId":"utile","quantity":1,"surroundLines":[{"part_code":"TP61","qty":1,"length_mm":1360,"label":"Nosing in Solid Redwood"},{"part_code":"TP68","qty":2,"length_mm":1400,"label":"Ogee Architrave – height"},{"part_code":"TP68","qty":1,"length_mm":1310,"label":"Ogee Architrave – width"}]},"children":[{"key":"paint_dw30p78","part_type":"paintAndIronmongeryPart","values":{"internalFinish":"clean_white","externalFinish":"clean_white","cillFinish":"clean_white","cutOutBrickReveal":false,"ironmongeryFinish":"PB","isCasementMpls":true},"children":[]},{"key":"notes_2jbii7c","part_type":"notesPart","values":{},"children":[]},{"key":"price_0x3y389","part_type":"pricePart","values":{},"children":[]},{"key":"frame_21ql7f6","part_type":"assemblyFramePart","values":{"width":1205,"height":1295,"leftWidth":37,"rightWidth":37,"topHeight":47,"bottomHeight":47,"frameDepth":96,"jambType":"solid_profiled","frameHeadStopSize":20,"frameStileStopSize":20,"cillStopSize":20,"cillAngle":6,"rakeFrame":false,"archHead":false},"children":[{"key":"mull_hn99n7y","part_type":"mullionPart","values":{"offset":543,"thicknessInFrame":27,"mullionStopSize":20,"startDivider":"0","endDivider":"0"},"children":[]},{"key":"trans_efwrx0d","part_type":"transomPart","values":{"offset":354,"thicknessInFrame":27,"transomStopSize":20,"startDivider":"mull_hn99n7y","endDivider":"0"},"children":[]},{"key":"cas_tjb08fz","part_type":"casementSashPart","values":{"operation":"left_hand_hung","casementTypeId":"open_out","thickness":54,"topHeight":62,"leftWidth":62,"rightWidth":62,"bottomHeight":83,"mechanicalClearanceLeft":4,"mechanicalClearanceRight":4,"mechanicalClearanceTop":4,"mechanicalClearanceBottom":4,"btmRailShapeId":"square","toBeReplaced":true},"children":[{"key":"cas_tjb08fz_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":16,"glazingTolerance":2},"children":[]}]},{"key":"casementSash_wq7tb56","part_type":"casementSashPart","values":{"operation":"top_hung","casementTypeId":"open_out","thickness":54,"topHeight":62,"leftWidth":62,"rightWidth":62,"bottomHeight":62,"mechanicalClearanceLeft":4,"mechanicalClearanceRight":4,"mechanicalClearanceTop":4,"mechanicalClearanceBottom":4,"btmRailShapeId":"square","toBeReplaced":true},"children":[{"key":"glass_6v7b2m3","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":16,"glazingTolerance":2},"children":[]}]},{"key":"casementSash_lvu3rhi","part_type":"casementSashPart","values":{"operation":"fix","casementTypeId":"open_out","thickness":54,"topHeight":62,"leftWidth":62,"rightWidth":62,"bottomHeight":83,"mechanicalClearanceLeft":4,"mechanicalClearanceRight":4,"mechanicalClearanceTop":4,"mechanicalClearanceBottom":4,"btmRailShapeId":"square","toBeReplaced":true},"children":[{"key":"glass_nexi099","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":16,"glazingTolerance":2},"children":[]}]},{"key":"cill_ycvom4k","part_type":"cillPart","values":{"height":47,"depth":128},"children":[]}]}]}},{"name":"Fanlight Over Fixed With Full-Height Opener (Configuration 3)","sort_order":70,"tree":{"key":"item_4iqihz7","part_type":"drawingItemPart","values":{"typeOfWork":"complete_new","frameMaterialId":"softwood","sashMaterialId":"softwood","cillMaterialId":"utile","quantity":1,"surroundLines":[{"part_code":"TP61","qty":1,"length_mm":1360,"label":"Nosing in Solid Redwood"},{"part_code":"TP68","qty":2,"length_mm":1400,"label":"Ogee Architrave – height"},{"part_code":"TP68","qty":1,"length_mm":1310,"label":"Ogee Architrave – width"}]},"children":[{"key":"paint_rx8xulv","part_type":"paintAndIronmongeryPart","values":{"internalFinish":"clean_white","externalFinish":"clean_white","cillFinish":"clean_white","cutOutBrickReveal":false,"ironmongeryFinish":"PB","isCasementMpls":true},"children":[]},{"key":"notes_if5amak","part_type":"notesPart","values":{},"children":[]},{"key":"price_r8p3m8d","part_type":"pricePart","values":{},"children":[]},{"key":"frame_c3lqy96","part_type":"assemblyFramePart","values":{"width":1205,"height":1295,"leftWidth":37,"rightWidth":37,"topHeight":47,"bottomHeight":47,"frameDepth":96,"jambType":"solid_profiled","frameHeadStopSize":20,"frameStileStopSize":20,"cillStopSize":20,"cillAngle":6,"rakeFrame":false,"archHead":false},"children":[{"key":"mull_llqcvke","part_type":"mullionPart","values":{"offset":561,"thicknessInFrame":27,"mullionStopSize":20,"startDivider":"0","endDivider":"0"},"children":[]},{"key":"trans_ps5dix8","part_type":"transomPart","values":{"offset":354,"thicknessInFrame":27,"transomStopSize":20,"startDivider":"0","endDivider":"mull_llqcvke"},"children":[]},{"key":"cas_9fjxau8","part_type":"casementSashPart","values":{"operation":"top_hung","casementTypeId":"open_out","thickness":54,"topHeight":62,"leftWidth":62,"rightWidth":62,"bottomHeight":62,"mechanicalClearanceLeft":4,"mechanicalClearanceRight":4,"mechanicalClearanceTop":4,"mechanicalClearanceBottom":4,"btmRailShapeId":"square","toBeReplaced":true},"children":[{"key":"cas_9fjxau8_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":16,"glazingTolerance":2},"children":[]}]},{"key":"casementSash_p3tehml","part_type":"casementSashPart","values":{"operation":"right_hand_hung","casementTypeId":"open_out","thickness":54,"topHeight":62,"leftWidth":62,"rightWidth":62,"bottomHeight":83,"mechanicalClearanceLeft":4,"mechanicalClearanceRight":4,"mechanicalClearanceTop":4,"mechanicalClearanceBottom":4,"btmRailShapeId":"square","toBeReplaced":true},"children":[{"key":"glass_3e6hfmh","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":16,"glazingTolerance":2},"children":[]}]},{"key":"casementSash_csucf1x","part_type":"casementSashPart","values":{"operation":"fix","casementTypeId":"open_out","thickness":54,"topHeight":62,"leftWidth":62,"rightWidth":62,"bottomHeight":83,"mechanicalClearanceLeft":4,"mechanicalClearanceRight":4,"mechanicalClearanceTop":4,"mechanicalClearanceBottom":4,"btmRailShapeId":"square","toBeReplaced":true},"children":[{"key":"glass_cyo32xc","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":16,"glazingTolerance":2},"children":[]}]},{"key":"cill_xdija5z","part_type":"cillPart","values":{"height":47,"depth":128},"children":[]}]}]}}]'::jsonb;
  _row           record;
  _tree          jsonb;
BEGIN
  SELECT id INTO _profile_id FROM public.default_profiles
  WHERE code = 'casement' AND is_active = TRUE;
  IF _profile_id IS NULL THEN
    RAISE EXCEPTION 'No active default_profiles row with code ''casement'' — the casement profile must exist first';
  END IF;

  SELECT code INTO _casement_code FROM public.reference_options
  WHERE category = 'product' AND lower(label) = 'casement' AND is_active
  ORDER BY sort_order LIMIT 1;
  IF _casement_code IS NULL THEN
    RAISE EXCEPTION 'No active reference_options row with category ''product'' and label ''Casement'' — run: SELECT code, label FROM reference_options WHERE category = ''product'' ORDER BY sort_order;';
  END IF;

  IF jsonb_array_length(_templates) <> 4 THEN
    RAISE EXCEPTION 'Expected 4 templates in this script, found %', jsonb_array_length(_templates);
  END IF;

  FOR _row IN
    SELECT * FROM jsonb_to_recordset(_templates) AS x(name text, sort_order int, tree jsonb)
  LOOP
    _tree := jsonb_set(_row.tree, '{values,product}', to_jsonb(_casement_code), true);

    IF EXISTS (SELECT 1 FROM public.drawing_templates WHERE name = _row.name) THEN
      -- Updated in place, so re-running never duplicates a template and
      -- never changes one a surveyor has since renamed.
      UPDATE public.drawing_templates
      SET tree = _tree, default_profile_id = _profile_id,
          sort_order = _row.sort_order, updated_at = now()
      WHERE name = _row.name;
      RAISE NOTICE 'Step AV-1: % updated in place', _row.name;
    ELSE
      INSERT INTO public.drawing_templates
        (name, family, group_name, window_type, default_profile_id, tree, sort_order, is_active)
      VALUES (_row.name, 'casement', 'Combination Flush Casements', 'Casement',
              _profile_id, _tree, _row.sort_order, TRUE);
      RAISE NOTICE 'Step AV-1: % created', _row.name;
    END IF;
  END LOOP;
END $$;

COMMIT;

-- ── Checks ─────────────────────────────────────────────────────────────────

-- 1. The casement templates, the four new ones in their own group, each with
--    Product and Quantity set.
SELECT name, group_name, sort_order, is_active,
       tree #>> '{values,product}'  AS product_code,
       tree #>> '{values,quantity}' AS quantity
FROM   public.drawing_templates
WHERE  family = 'casement'
ORDER  BY sort_order;

-- 2. Each new template's shape: the divider offsets, which divider stops at
--    another (a startDivider / endDivider other than '0'), the operations and
--    the surround list. Expect 7 and 13/14 to show one non-'0' reference and
--    12 to show none.
SELECT t.name,
       (SELECT jsonb_agg(v) FROM jsonb_path_query(t.tree, '$.**.values.offset') v)       AS divider_offsets,
       (SELECT jsonb_agg(v) FROM jsonb_path_query(t.tree, '$.**.values.startDivider') v) AS start_dividers,
       (SELECT jsonb_agg(v) FROM jsonb_path_query(t.tree, '$.**.values.endDivider') v)   AS end_dividers,
       (SELECT jsonb_agg(v) FROM jsonb_path_query(t.tree, '$.**.values.operation') v)    AS operations
FROM   public.drawing_templates t
WHERE  t.group_name = 'Combination Flush Casements'
ORDER  BY t.sort_order;

-- 3. The surround list, and exactly one nosing (TP61) per template — the
--    deep window board that fires rule 251.
SELECT t.name,
       t.tree #> '{values,surroundLines}' AS surrounds,
       (SELECT count(*) FROM jsonb_array_elements(t.tree #> '{values,surroundLines}') l
        WHERE l ->> 'part_code' = 'TP61') AS nosings
FROM   public.drawing_templates t
WHERE  t.group_name = 'Combination Flush Casements'
ORDER  BY t.sort_order;


-- ---------------------------------------------------------------------------
-- DO NOT RUN — rollback, only if this step has to be undone
-- ---------------------------------------------------------------------------
-- DELETE FROM public.drawing_templates
-- WHERE group_name = 'Combination Flush Casements'
--   AND name IN (
--     'Double Casement With Fanlight',
--     'Fanlight Over Each Casement (Configuration 1)',
--     'Full-Height Opener With Fanlight Over Fixed (Configuration 2)',
--     'Fanlight Over Fixed With Full-Height Opener (Configuration 3)'
--   );
